// A abertura se baseia nas casas do mapa, inclusive os baixios da maré alta.
export function limitesDaTravessia(mapa, {origemX, origemY}, lado) {
  let esquerda = Infinity, cima = Infinity, direita = 0, baixo = 0;
  mapa.forEach((linha, y) => {
    for (let x = 0; x < linha.length; x++) {
      if (linha[x] === '#') continue;
      esquerda = Math.min(esquerda, x);
      cima = Math.min(cima, y);
      direita = Math.max(direita, x + 1);
      baixo = Math.max(baixo, y + 1);
    }
  });
  return [origemX + esquerda * lado, origemY + cima * lado,
    origemX + direita * lado, origemY + baixo * lado];
}

const LADO_DA_CASA = 48;

export function enquadrarTravessia(width, height, bounds, densidade = 1) {
  const [x0, y0, x1, y1] = bounds;
  const ladoCurto = Math.min(width, height);
  const moldura = Math.min(8 * densidade, Math.round(ladoCurto * .022));
  const margem = Math.round(ladoCurto * .058) + Math.ceil(moldura);
  // A caixa jogável é um múltiplo de 48. dimensionar por casa inteira
  // mantém as junções na grade e ganha zoom em passos de 1/48.
  const colunas = (x1 - x0) / LADO_DA_CASA;
  const linhas = (y1 - y0) / LADO_DA_CASA;
  const pixelsPorCasa = Math.floor(Math.min((width - 2 * margem) / colunas,
    (height - 2 * margem) / linhas));
  const scale = pixelsPorCasa / LADO_DA_CASA;
  return {width, height, scale, pixelsPorCasa, bounds, margem, moldura,
    left: Math.round((width - (x0 + x1) * scale) / 2),
    top: Math.round((height - (y0 + y1) * scale) / 2)};
}

function pintarMoldura(ctx, {width: w, height: h, moldura}) {
  const p = Math.max(2, Math.round(moldura));
  ctx.fillStyle = '#cbd0b0';
  ctx.fillRect(p * 3, 0, w - p * 6, p);
  ctx.fillRect(p * 3, h - p, w - p * 6, p);
  ctx.fillRect(0, p * 3, p, h - p * 6);
  ctx.fillRect(w - p, p * 3, p, h - p * 6);
  for (const x of [0, w - p]) for (const y of [0, h - p]) {
    const dx = x ? -p : p;
    const dy = y ? -p : p;
    for (const [i, j] of [[0,2],[1,2],[1,1],[2,1],[2,0]]) ctx.fillRect(x + i * dx, y + j * dy, p, p);
  }
  const tom = (i) => i % 2 ? '#e7e7cb' : '#b8c2a7';
  for (let x = p * 7, i = 0; x < w - p * 4; x += p * 13, i++) {
    ctx.fillStyle = tom(i);
    ctx.fillRect(x, 0, p, p);
    ctx.fillRect(w - x - p, h - p, p, p);
  }
  for (let y = p * 9, i = 0; y < h - p * 4; y += p * 16, i++) {
    ctx.fillStyle = tom(i);
    ctx.fillRect(0, y, p, p);
    ctx.fillRect(w - p, h - y - p, p, p);
  }
}

// Compara resoluções do canvas sem alterar o tamanho CSS. Quando duas
// opções dão o mesmo enquadramento, fica com o canvas menor.
export function escolherResolucaoDaCamera(largura, altura, bounds, dpr) {
  const orcamento = 6000000;
  const avaliar = (densidade) => {
    const geometria = enquadrarTravessia(Math.round(largura*densidade),
      Math.round(altura*densidade), bounds, densidade);
    return {...geometria, densidade, escalaNaTela:geometria.scale/densidade};
  };
  let melhor = avaliar(dpr);
  for(let densidade=Math.max(2,Math.ceil(dpr));densidade<=4;densidade++){
    if(largura*altura*densidade**2>orcamento)break;
    const proxima=avaliar(densidade);
    if(proxima.escalaNaTela>melhor.escalaNaTela+1e-9)melhor=proxima;
  }
  return melhor;
}

