export const corDoOceano=()=> '#142e47';
export function paintCameraBackground(ctx,width,height,seed) {
 const {world,cor}=typeof seed==='string'?{world:seed}:seed??{};
 ctx.save();
 ctx.fillStyle=corDoOceano(world,cor);
 ctx.fillRect(0,0,width,height);
 ctx.restore();
}
const sobrepoe=([a,b,c,d],[x,y,r,s])=>x<c&&a<r&&y<d&&b<s;
const ativos=new Map();
const poses=new WeakMap();
function ctxArte(nome,owner){
 if(ativos.has(nome))return ativos.get(nome);
 const {largura,altura,linhas}=SPRITES_CAMARA[nome];
 const c=owner?.createElement('canvas');
 if(!c)return;
 c.width=largura;c.height=altura;
 const ctx=c.getContext('2d');
 for(const [cor,x,y,w] of linhas){ctx.fillStyle=cor;ctx.fillRect(x,y,w,1);}
 ativos.set(nome,c);return c;
}
function retanguloLivre(d,x,y,w,h,ctx,destinos,fonte){
 const {canvas,bounds,width,height,left,top,scale,world,cor}=d;
 const margem=5, borda=Math.max(1,Math.ceil(d.moldura??1));
 const p=[x-margem,y-margem,x+w+margem,y+h+margem];
 const [a,b,c,e]=p;
 if(a*scale+left<borda||b*scale+top<borda||c*scale+left>width-borda||e*scale+top>height-borda)return false;
 if(sobrepoe(p,bounds)||destinos.some(r=>sobrepoe(p,r)))return false;
 const x0=Math.max(0,a),x1=Math.min(canvas.width,c),y0=Math.max(0,b),y1=Math.min(canvas.height,e);
 // Extensão do cenário já é água. Dentro da fonte, proteger tudo salvo
 // a cor base garante que a cunha não cubra nem um reflexo, nem espuma.
 if(x1<=x0||y1<=y0)return true;
 if(!fonte)return false;
 const rgb=[20,46,71];
 for(let j=y0;j<y1;j++)for(let i=x0;i<x1;i++){
  const k=4*(j*canvas.width+i);
  if(fonte[k]!==rgb[0]||fonte[k+1]!==rgb[1]||fonte[k+2]!==rgb[2]||fonte[k+3]!==255)return false;
 }
 return true;
}
function decidir(d,originais,fonte){
 const {canvas,bounds,width,height,left,top,scale,world}=d;
 const borda=Math.max(1,Math.ceil(d.moldura??1));
 const visible=[(borda-left)/scale,(borda-top)/scale,(width-borda-left)/scale,(height-borda-top)/scale];
 const tem=(e)=>originais.some(([x,y,w,h,farol])=>e(farol)&&sobrepoe(visible,[x+w*.10,y+h*.12,x+w*.90,y+h*.88]));
 const precisaRocha=!tem(v=>v===0);
 if(!precisaRocha)return [];
 const mostrar=[],destinos=[];
 for(const nome of ['cunha']){
   const {largura:w,altura:h}=SPRITES_CAMARA[nome];
  const [a,b,c,e]=visible;
  const yMin=Math.ceil(b+6), yMax=Math.floor(e-h-6);
  const xMin=Math.ceil(a+6), xMax=Math.floor(c-w-6);
  if(xMax<xMin||yMax<yMin)continue;
  const alvoY=Math.round(nome==='farol'?yMax:b+(e-b)*.24);
  const candidatos=[];
  for(let y=yMin;y<=yMax;y+=4)for(let x=xMin;x<=xMax;x+=4)candidatos.push([x,y]);
  for(const x of [xMin,xMax])for(const y of [yMin,yMax])candidatos.push([x,y]);
  const margemNivel=(x)=>Math.max(bounds[0]-(x+w),x-bounds[2]);
  candidatos.sort(([x,y],[u,v])=>Math.abs(y-alvoY)-Math.abs(v-alvoY)||margemNivel(u)-margemNivel(x));
  const alvo=candidatos.find(([x,y])=>retanguloLivre(d,x,y,w,h,null,destinos,fonte));
  if(alvo){const [x,y]=alvo;destinos.push([x,y,x+w,y+h]);mostrar.push([nome,x,y]);}
 }
 return mostrar;
}
// Mesmos quadradinhos e cruzes do fundo do Arquipélago. O cenário usa
// a grade da cena; a semente não depende da maré nem dos movimentos.
const PARTICULAS_HUB=['#23465d','#2a5269','#386078','#497085'];
const ESTRELAS_HUB=[['#477891','#6f9caf'],['#6195a6','#9ac5d0']];
function particulas(d,fonte,ocultos,originais,id,farol){
 const {scale,left,top,width,height}=d;
 const reservas=originais.map(([x,y,w,h])=>[x,y,x+w,y+h]);
 for(const [nome,x,y] of ocultos){
  const a=SPRITES_CAMARA[nome];reservas.push([x,y,x+a.largura,y+a.altura]);
 }
 const r=[-left/scale,-top/scale,(width-left)/scale,(height-top)/scale];
 let semente=2166136261;
 for(const c of id)semente=Math.imul(semente^c.charCodeAt(0),16777619);
 function sorteio(t){
  let s=(semente+Math.imul(t+1,0x9e3779b1))|0;
  s=Math.imul(s^(s>>>16),0x7feb352d);
  s=Math.imul(s^(s>>>15),0x846ca68b);
  return ((s^(s>>>16))>>>0)/0x100000000;
 }
 const motivo= Math.max(1,Math.round(1/scale));
 const pontos=[];
 if(farol)reservas.push([(farol[0]-left)/scale,(farol[1]-top)/scale,
  (farol[0]+farol[2]-left)/scale,(farol[1]+farol[3]-top)/scale]);

 const ref=width*height/((d.densidade||1)**2);
 const nEstrelas=Math.max(2,Math.round(ref*11/(1920*1080)));
 const nParticulas=Math.max(6,Math.round(ref*32/(1920*1080)));
 for (const [classe,total] of [['brilho',nEstrelas],['particula',nParticulas]]) {
  for(let i=0;i<total;i++){
   const grande=classe==='brilho'?i%4===3:i%5===4;
   const lado=(classe==='brilho'?(grande?5:3):(grande?3:2))*motivo;
   const setor=(i%3);
   for(let t=0;t<32;t++){
    const indice=(classe==='brilho'?0:65536)+i*64+t*2;
    const x=Math.floor((r[0]+(r[2]-r[0])*(setor+sorteio(indice))/3)/motivo)*motivo;
    const y=Math.floor((r[1]+(r[3]-r[1])*sorteio(indice+1))/motivo)*motivo;
    if(!retanguloLivre(d,x,y,lado,lado,null,reservas,fonte))continue;
    pontos.push({x,y,classe,grande,motivo,lado,tom:grande?2:i%2});
    // Guarda um respiro entre elementos sem engolir os reflexos originais.
    reservas.push([x-motivo,y-motivo,x+lado+motivo,y+lado+motivo]);
    break;
   }
  }
 }
 return pontos;
}
export function decorateCamera(ctx,d){
 const {canvas,phase,world,width,height,left,top,scale,bounds}=d;
 const id=typeof phase==='string'?phase:phase?.id;
 const originais=OCEANO_POR_FASE[id]??[];
 if(!id||!Number.isFinite(scale)||scale<=0||!bounds?.every(Number.isFinite))return [];
 const chave=[id,world,width,height,left,top,scale,d.moldura,canvas.width,canvas.height,...bounds].join(':');
 let memo=poses.get(canvas);
 if(memo?.chave!==chave){
  const fonte=canvas.getContext('2d')?.getImageData(0,0,canvas.width,canvas.height)?.data;
  const mostrar=originais.length?decidir(d,originais,fonte):[];
  const farol=posicionarFarolNaBorda(d,originais,mostrar,fonte);
  memo={chave,mostrar,farol,pontos:particulas(d,fonte,mostrar,originais,id,farol)};
  poses.set(canvas,memo);
 }
 const foraDaFonte=(x,y,w,h)=>!sobrepoe([0,0,canvas.width,canvas.height],[x,y,x+w,y+h]);
 ctx.save();ctx.imageSmoothingEnabled=false;
 for(const {x,y,classe,grande,motivo,lado,tom} of memo.pontos){
  if(d.efeitoNoMar&&!foraDaFonte(x,y,lado,lado))continue;
  const px=Math.round(x*scale+left),py=Math.round(y*scale+top);
  const p=Math.max(1,Math.round(motivo*scale)), l=p*(lado/motivo);
  if(classe==='brilho'){
   const [raios,centro]=ESTRELAS_HUB[Number(grande)], m=(l-p)/2;
   ctx.fillStyle=raios;
   ctx.fillRect(px,py+m,l,p);
   ctx.fillRect(px+m,py,p,l);
   ctx.fillStyle=centro;
   ctx.fillRect(px+m,py+m,p,p);
  }else{
   ctx.fillStyle=PARTICULAS_HUB[tom];
   ctx.fillRect(px,py,l,l);
   if(grande){ctx.fillStyle=PARTICULAS_HUB[3];ctx.fillRect(px+p,py,p,p);}
  }
 }
 for(const [nome,x,y] of memo.mostrar){
  const arte=ctxArte(nome,canvas.ownerDocument??globalThis.document);
  if(!arte||(d.efeitoNoMar&&!foraDaFonte(x,y,arte.width,arte.height)))continue;
  const px=Math.round(x*scale+left),py=Math.round(y*scale+top);
  ctx.drawImage(arte,px,py,Math.max(1,Math.round(arte.width*scale)),Math.max(1,Math.round(arte.height*scale)));
 }
 if(memo.farol){
  const arte=ctxArte('farol',canvas.ownerDocument??globalThis.document);
  if(arte)ctx.drawImage(arte,...memo.farol);
 }
 ctx.restore();
 return memo.mostrar;
}

