function prepararAcoesVitoria(mostrar){
  if(mostrar)mostrouAcoesVitoria=true;
  const grupo=buscar('#acoes-vitoria-fase');
  const vitoria=mostrouAcoesVitoria&&tela==='fase'&&modoCampanha()&&estado.situacao==='vitoria';
  grupo.hidden=!vitoria;
  const voltarJogo=buscar('#voltar-seletor-fase');
  const tinhaFoco=vitoria&&document.activeElement===voltarJogo;
  voltarJogo.hidden=vitoria;
  if(tinhaFoco)buscar('#voltar-vitoria-fase').focus({preventScroll:true});
  const proxima=vitoria?proximaFaseDoSeletor():undefined;
  const botao=buscar('#proximo-nivel');
  botao.hidden=!proxima;
  const bloqueada=proxima?.estado==='bloqueada';
  if(proxima)botao.setAttribute('aria-label','Próximo nível: '+proxima.nome+
    (bloqueada?'. Bloqueado. '+(proxima.motivo??'Conclua os desafios anteriores.'):''));
  else botao.removeAttribute('aria-label');
  if(bloqueada){
    botao.setAttribute('aria-disabled','true');
    botao.setAttribute('title',proxima.motivo??'Conclua os desafios anteriores.');
  }else{
    botao.removeAttribute('aria-disabled');
    botao.removeAttribute('title');
  }
}
